(function() {
  const encoderSelect = document.getElementById('encoder-mode');
  const feedbackBox = document.getElementById('training-feedback');
  const decodeRadios = document.querySelectorAll('input[name="decode-strat"]');
  const vizContainer = document.getElementById('decode-viz');

  // 训练配置交互
  encoderSelect.addEventListener('change', function() {
    const mode = this.value;
    if (mode === 'frozen') {
      feedbackBox.innerHTML = `
        <strong>当前策略：</strong> 冻结文档编码器和索引。<br>
        <strong>理由：</strong> 避免像 REALM 那样定期更新索引的高昂成本。实验发现此步骤对于获得强劲性能并非必要。<br>
        <strong>优化对象：</strong> 仅微调查询编码器 (BERTq) 和 BART 生成器。
      `;
      feedbackBox.style.background = '#f0f7ff';
      feedbackBox.style.borderLeftColor = '#0056b3';
    } else {
      feedbackBox.innerHTML = `
        <strong>警告：</strong> 更新文档编码器 (BERTd) 成本高昂。<br>
        <strong>原因：</strong> 需要像 REALM 那样定期重新计算整个文档索引。<br>
        <strong>建议：</strong> 原文采用冻结策略并取得报告结果；未提供更新文档编码器的同条件对照，本演示不推断哪种策略普遍更优。
      `;
      feedbackBox.style.background = '#fff3e0';
      feedbackBox.style.borderLeftColor = '#ff9800';
    }
  });

  // 解码策略可视化
  function updateDecodeViz() {
    const selected = document.querySelector('input[name="decode-strat"]:checked').value;
    let html = '';

    if (selected === 'token') {
      html = `
        <div class="viz-step">
          <strong>RAG-Token 解码</strong><br>
          可视为标准自回归 seq2seq 生成器。
        </div>
        <div class="viz-step">
          转移概率已对文档边缘化：<br>
          <code>p'(yi|x, y1:i-1) = Σ pη(z|x)pθ(yi|x, z, y1:i-1)</code>
        </div>
        <div class="viz-step highlight">
          ✅ 可直接插入标准束搜索解码器 (Standard Beam Decoder)
        </div>
      `;
    } else if (selected === 'seq-thorough') {
      html = `
        <div class="viz-step">
          <strong>RAG-Sequence: Thorough Decoding (彻底)</strong><br>
          似然 p(y|x) 无法分解为逐 token 概率。
        </div>
        <div class="viz-step">
          1. 对每个文档 z 运行束搜索，得到假设集 Y。
        </div>
        <div class="viz-step highlight">
          2. 对未出现在束中的假设 y，为每个文档 z 运行额外前向传播。<br>
          计算 pθ(y|x, z) * pη(z|x) 并求和。
        </div>
        <div class="viz-step">
          <span style="color:#d32f2f">⚠ 计算量大：长序列时 |Y| 很大，需多次前向传播。</span>
        </div>
      `;
    } else if (selected === 'seq-fast') {
      html = `
        <div class="viz-step">
          <strong>RAG-Sequence: Fast Decoding (快速)</strong><br>
          为 Thorough 的近似策略。
        </div>
        <div class="viz-step">
          1. 对每个文档 z 运行束搜索，得到假设集 Y。
        </div>
        <div class="viz-step highlight">
          2. 假设未在束中生成的候选者概率约为零：<br>
          <code>pθ(y|x, zi) ≈ 0</code>
        </div>
        <div class="viz-step">
          ✅ 避免额外前向传播，提高长序列生成效率。
        </div>
      `;
    }

    vizContainer.innerHTML = html;
  }

  decodeRadios.forEach(radio => {
    radio.addEventListener('change', updateDecodeViz);
  });

  // 初始化
  updateDecodeViz();

  // 来源按钮事件代理
  document.querySelector('.chapter-container').addEventListener('click', function(e) {
    if (e.target.matches('[data-source]')) {
      const sourceId = e.target.getAttribute('data-source');
      // 宿主内核将处理此事件，此处仅做无操作或日志（若允许）
      // 根据规范，不自行 postMessage，由宿主桥接
    }
  });
})();
